// Core tests: the 16 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC. Every expected value below was computed by hand from the SPEC's
// integer rules; the hand derivations are listed in AUTHOR-CHECK.md
// section 2. Independent re-derivations (a second hand pass over the
// same pinned formulas) are noted inline where they add a new value.

import assert from "node:assert/strict";
import test from "node:test";
import {
  formatAverageMl,
  formatWeightKg,
  run,
} from "../public/js/core/baby-feeding.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = { weight: "4", factor: "150", feedsPerDay: "8", ageMonths: "" };

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("worked anchors: 5 kg x 150 / 10 feeds is 75 ml each; 2.5 kg x 200 / 5 feeds is 100 ml each", () => {
  // Hand: 500 x 150 = 75000 -> 750 ml; 750 = 10 x 75 + 0. 250 x 200 =
  // 50000 -> 500 ml; 500 = 5 x 100 + 0.
  const first = run({ ...base, weight: "5", feedsPerDay: "10" });
  assert.equal(first.ok, true);
  assert.equal(first.result.dailyTotalMl, 750);
  assert.deepEqual(first.result.perFeedMl, [75, 75, 75, 75, 75, 75, 75, 75, 75, 75]);
  assert.equal(first.result.perFeedAverageMl, 75);
  const second = run({ ...base, weight: "2.5", factor: "200", feedsPerDay: "5" });
  assert.equal(second.ok, true);
  assert.equal(second.result.dailyTotalMl, 500);
  assert.deepEqual(second.result.perFeedMl, [100, 100, 100, 100, 100]);
});

test("boundary: weight 15.00 succeeds, 15.01 is RANGE; 1.00 succeeds, 0.99 is RANGE", () => {
  // 1500 x 150 = 225000 -> 2250 ml; 1500 x 200 already covered by the
  // max-boundary fixture. 100 x 150 = 15000 -> 150 ml (min-boundary).
  const max = run({ ...base, weight: "15.00", factor: "150", feedsPerDay: "8" });
  assert.equal(max.ok, true);
  assert.equal(max.result.dailyTotalMl, 2250);
  assert.equal(max.result.weightKg, 15);
  assert.deepEqual(errorOf({ ...base, weight: "15.01" }), {
    code: "RANGE",
    field: "weight",
    row: null,
  });
  const min = run({ ...base, weight: "1.00" });
  assert.equal(min.ok, true);
  assert.equal(min.result.dailyTotalMl, 150);
  assert.deepEqual(errorOf({ ...base, weight: "0.99" }), {
    code: "RANGE",
    field: "weight",
    row: null,
  });
});

test("boundary: factor 150 and 200 succeed, 149 and 201 are RANGE", () => {
  // 4 kg x 150 = 600; 4 kg x 200 = 800, 800 = 8 x 100 + 0.
  assert.equal(run({ ...base, factor: "150" }).result.dailyTotalMl, 600);
  const top = run({ ...base, factor: "200" });
  assert.equal(top.ok, true);
  assert.equal(top.result.dailyTotalMl, 800);
  assert.deepEqual(errorOf({ ...base, factor: "149" }), {
    code: "RANGE",
    field: "factor",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, factor: "201" }), {
    code: "RANGE",
    field: "factor",
    row: null,
  });
});

test("boundary: feeds 1 and 24 succeed, 0 and 25 are RANGE", () => {
  const one = run({ ...base, feedsPerDay: "1" });
  assert.equal(one.ok, true);
  assert.deepEqual(one.result.perFeedMl, [600]);
  const many = run({ ...base, feedsPerDay: "24" });
  assert.equal(many.ok, true);
  assert.equal(many.result.perFeedMl.length, 24);
  assert.deepEqual(errorOf({ ...base, feedsPerDay: "0" }), {
    code: "RANGE",
    field: "feedsPerDay",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, feedsPerDay: "25" }), {
    code: "RANGE",
    field: "feedsPerDay",
    row: null,
  });
});

test("boundary: age 0 and 24 are accepted with the pinned notices; 25 is RANGE", () => {
  const newborn = run({ ...base, ageMonths: "0" });
  assert.equal(newborn.ok, true);
  assert.deepEqual(newborn.result.notices, ["early-newborn-amounts-differ"]);
  const oldest = run({ ...base, ageMonths: "24" });
  assert.equal(oldest.ok, true);
  assert.deepEqual(oldest.result.notices, ["guideline-covers-to-about-6-months"]);
  assert.deepEqual(errorOf({ ...base, ageMonths: "25" }), {
    code: "RANGE",
    field: "ageMonths",
    row: null,
  });
  // Age 6 is inside the guideline window: no notice. Age 7 is the
  // first month past it.
  assert.deepEqual(run({ ...base, ageMonths: "6" }).result.notices, []);
  assert.deepEqual(run({ ...base, ageMonths: "7" }).result.notices, [
    "guideline-covers-to-about-6-months",
  ]);
});

test("age with a leading zero parses as the same month and never changes the amounts", () => {
  const plain = run({ ...base, ageMonths: "9" });
  const padded = run({ ...base, ageMonths: "09" });
  assert.equal(padded.ok, true);
  assert.equal(padded.result.ageMonths, 9);
  assert.equal(padded.result.dailyTotalMl, plain.result.dailyTotalMl);
  assert.deepEqual(padded.result.perFeedMl, plain.result.perFeedMl);
  assert.deepEqual(padded.result.notices, plain.result.notices);
});

test("weight grammar: leading dot, trailing dot, 3 decimals, sign, exponent and full-width digits are DECIMAL_FORMAT", () => {
  for (const bad of [".5", "4.", "4.555", "-4", "+4", "4e2", "４.5", "4.5 ", "4,5"]) {
    assert.deepEqual(errorOf({ ...base, weight: bad }), {
      code: "DECIMAL_FORMAT",
      field: "weight",
      row: null,
    });
  }
  // Leading zeros are allowed: 04.50 = 4.5 kg -> 455 x 150 = 68250 ->
  // 683 ml (same total as the .5-tie fixture).
  const leadingZero = run({ ...base, weight: "04.50", feedsPerDay: "7" });
  assert.equal(leadingZero.ok, true);
  assert.equal(leadingZero.result.weightKg, 4.5);
  assert.equal(leadingZero.result.dailyTotalMl, 675);
});

test("integer grammar: decimals and non-digits are INTEGER_FORMAT on factor, feeds and age", () => {
  assert.deepEqual(errorOf({ ...base, factor: "150.5" }), {
    code: "INTEGER_FORMAT",
    field: "factor",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, factor: "abc" }), {
    code: "INTEGER_FORMAT",
    field: "factor",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, feedsPerDay: "8.0" }), {
    code: "INTEGER_FORMAT",
    field: "feedsPerDay",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, ageMonths: "3.5" }), {
    code: "INTEGER_FORMAT",
    field: "ageMonths",
    row: null,
  });
  // Factor with a leading zero is the same factor.
  const padded = run({ ...base, factor: "0150" });
  assert.equal(padded.ok, true);
  assert.equal(padded.result.factorMlPerKgDay, 150);
});

test("capacity: a 9-unit value is INPUT_LIMIT on every field, before grammar and range", () => {
  assert.deepEqual(errorOf({ ...base, weight: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "weight",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, factor: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "factor",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, feedsPerDay: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "feedsPerDay",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, ageMonths: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "ageMonths",
    row: null,
  });
  // 8 units is the limit and passes capacity: "12345678" is grammar-
  // valid for weight but out of range, so RANGE (not INPUT_LIMIT).
  assert.deepEqual(errorOf({ ...base, weight: "12345678" }), {
    code: "RANGE",
    field: "weight",
    row: null,
  });
});

test("a lone surrogate is UNICODE, before EMPTY and grammar, on every field", () => {
  assert.deepEqual(errorOf({ ...base, weight: "\uD800" }), {
    code: "UNICODE",
    field: "weight",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, factor: "\uD800" }), {
    code: "UNICODE",
    field: "factor",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, feedsPerDay: "\uDC00" }), {
    code: "UNICODE",
    field: "feedsPerDay",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, ageMonths: "\uD800" }), {
    code: "UNICODE",
    field: "ageMonths",
    row: null,
  });
  // A paired surrogate is not UNICODE: it fails grammar instead.
  assert.deepEqual(errorOf({ ...base, weight: "\uD83D\uDE00" }), {
    code: "DECIMAL_FORMAT",
    field: "weight",
    row: null,
  });
});

test("EMPTY fires on each required field; an empty age is legal and means null", () => {
  assert.deepEqual(errorOf({ ...base, weight: "" }), {
    code: "EMPTY",
    field: "weight",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, factor: "" }), {
    code: "EMPTY",
    field: "factor",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, feedsPerDay: "" }), {
    code: "EMPTY",
    field: "feedsPerDay",
    row: null,
  });
  const noAge = run({ ...base, ageMonths: "" });
  assert.equal(noAge.ok, true);
  assert.equal(noAge.result.ageMonths, null);
  assert.deepEqual(noAge.result.notices, []);
});

test("the first field in the fixed order reports first", () => {
  assert.deepEqual(errorOf({ ...base, weight: "", factor: "149" }), {
    code: "EMPTY",
    field: "weight",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, factor: "149", feedsPerDay: "25" }), {
    code: "RANGE",
    field: "factor",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, feedsPerDay: "25", ageMonths: "25" }), {
    code: "RANGE",
    field: "feedsPerDay",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, weight: "4.555", factor: "149" }), {
    code: "DECIMAL_FORMAT",
    field: "weight",
    row: null,
  });
});

test("schema: extra key, missing key, wrong type, array, null, accessor and symbol key are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.factor;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, weight: 4 }), schema);
  assert.deepEqual(errorOf({ ...base, ageMonths: null }), schema);
  assert.deepEqual(errorOf(["4"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("4"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "weight", {
    enumerable: true,
    get() {
      return "4";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
  const withSymbol = { ...base, [Symbol("extra")]: "1" };
  assert.deepEqual(errorOf(withSymbol), schema);
  const stringObject = { ...base };
  stringObject.weight = new String("4");
  assert.deepEqual(errorOf(stringObject), schema);
});

test("property: per-feed amounts always sum to the daily total and every feed is at least 1 ml", () => {
  for (const weight of ["1", "1.01", "2.33", "4.55", "7.77", "12.34", "15"]) {
    for (const factor of ["150", "163", "175", "199", "200"]) {
      for (const feeds of ["1", "2", "3", "7", "8", "12", "24"]) {
        const outcome = run({ weight, factor, feedsPerDay: feeds, ageMonths: "" });
        assert.equal(outcome.ok, true);
        const sum = outcome.result.perFeedMl.reduce((a, b) => a + b, 0);
        assert.equal(sum, outcome.result.dailyTotalMl);
        assert.equal(outcome.result.perFeedMl.length, Number(feeds));
        assert.ok(outcome.result.perFeedMl.every((ml) => ml >= 1));
        // The split is monotone: the first feeds are never smaller
        // than the later ones, and neighbours differ by at most 1.
        const feedsList = outcome.result.perFeedMl;
        for (let i = 1; i < feedsList.length; i += 1) {
          assert.ok(feedsList[i - 1] >= feedsList[i]);
          assert.ok(feedsList[i - 1] - feedsList[i] <= 1);
        }
      }
    }
  }
});

test("property: age 0-24 never changes the total or the split, only ageMonths and notices", () => {
  const reference = run(base);
  assert.equal(reference.ok, true);
  for (let age = 0; age <= 24; age += 1) {
    const outcome = run({ ...base, ageMonths: String(age) });
    assert.equal(outcome.ok, true);
    assert.equal(outcome.result.dailyTotalMl, reference.result.dailyTotalMl);
    assert.deepEqual(outcome.result.perFeedMl, reference.result.perFeedMl);
    assert.equal(outcome.result.perFeedAverageMl, reference.result.perFeedAverageMl);
    assert.equal(outcome.result.ageMonths, age);
  }
});

test("half-up rounding: the .5 tie rounds up and the average .05 tie rounds up", () => {
  // 4.55 kg x 150 = 682.5 -> 683 (fixture); 6.35 kg x 150 = 952.5 ->
  // 953 (fixture). A non-tie just below: 4.54 kg x 150 = 681.0.
  assert.equal(run({ ...base, weight: "4.54", feedsPerDay: "7" }).result.dailyTotalMl, 681);
  // Average tie: 150 ml / 24 feeds = 6.25 -> 6.3 (the min-boundary
  // fixture). Non-tie average: 600 / 7 = 85.714... -> 85.7.
  assert.equal(run({ ...base, feedsPerDay: "7" }).result.perFeedAverageMl, 85.7);
});

test("the core does not mutate its input", () => {
  const input = { ...base, ageMonths: "9" };
  const snapshot = JSON.stringify(input);
  const outcome = run(input);
  assert.equal(outcome.ok, true);
  assert.equal(JSON.stringify(input), snapshot);
  const bad = { ...base, weight: "0.99" };
  const badSnapshot = JSON.stringify(bad);
  assert.equal(run(bad).ok, false);
  assert.equal(JSON.stringify(bad), badSnapshot);
});

test("display formatting: average one decimal, weight as the JSON number", () => {
  assert.equal(formatAverageMl(75), "75.0");
  assert.equal(formatAverageMl(97.6), "97.6");
  assert.equal(formatAverageMl(6.3), "6.3");
  assert.equal(formatWeightKg(4), "4");
  assert.equal(formatWeightKg(4.55), "4.55");
  assert.equal(formatWeightKg(15), "15");
});
